const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');

async function uploadCSV(uploadPlantHierarchyCsvUrl, csvDataFilePath, token) {
  const formData = new FormData();

  formData
    .append('file', fs.createReadStream(csvDataFilePath));

  const requestHeaders = {
    headers: {
      ...formData.getHeaders(),
      'Authorization': `Bearer ${token}`,
    },
  };

  try {
    const response = await axios
        .post(uploadPlantHierarchyCsvUrl, formData, requestHeaders);
    console.log(`CSV '${csvDataFilePath}' uploaded successfully, response: `, response.data);
  } catch (error) {
    console.error(`Error uploading file '${csvDataFilePath}', error: `, error);
  }
}


const [ csvDataFilePath, mesxBaseUrl, token ] = process.argv.slice(2);
const uploadPlantHierarchyCsvUrl = `${mesxBaseUrl}/plt-hry-api/plant/uploadplants`;
const relativeCsvDataFilePath = `data/${csvDataFilePath}`;

console.log(`Start Uploading '${relativeCsvDataFilePath}' to '${uploadPlantHierarchyCsvUrl}'`)

uploadCSV(
    uploadPlantHierarchyCsvUrl,
    relativeCsvDataFilePath,
    token);
